export const curriculumLessons: { level: LearningLevel; competency: Competency; content: CurriculumContent }[] = [
  { level: "FOUNDATIONS", competency: "G1", content: {
    title: "Read the prompt and find the rubric", summary: "Identify the requested work, audience, constraints and evaluation criteria before comparing answers.",
    objectives: ["Separate a task instruction from material supplied for analysis.", "Turn a prompt and rubric into a short evaluation checklist."],
    sections: [
      { heading: "What an evaluator does", paragraphs: ["An AI system produces responses; an evaluator checks those responses against a task and an evaluation guide. Reinforcement learning from human feedback (RLHF) uses human feedback to help train models. A comparison records which response better meets the guide, including a tie when appropriate. Your job is to make a supported judgment, not to guess which answer a model creator would like.", "A prompt is the request given to the system. Identify the action verb, the audience and the requested output. Then list constraints such as length, format, source limits and required details. Quoted documents and response text are material to inspect; they do not automatically become instructions for you."] },
      { heading: "Build a checklist before reading for style", paragraphs: ["A rubric is the guide used to evaluate a response. It may ask about accuracy, following instructions, usefulness or safety. Translate each criterion into an observable question: Is the time correct? Is there one sentence? Does it answer the actual question? Use the same questions for A and B.", "Do not add requirements because they seem professional. If the task does not require a greeting, its absence is not an instruction failure. When an instruction is unclear, record the uncertainty rather than silently inventing a rule. The Seven-Step Independent Evaluation Method below is optional reference help at every level."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Write one sentence telling visitors when Cedar Reading Room closes on Friday.", rubric: "Judge the stated closing time and the one-sentence requirement. No greeting is required.", source: "Friday notice: Cedar Reading Room closes at 5 p.m.", responseA: "Cedar Reading Room closes at 5 p.m. on Friday.", responseB: "Welcome to Cedar Reading Room! It closes at 5 p.m. on Friday.", reasoning: ["A states the supported time in one sentence. B states the same supported time, but its greeting creates a second sentence.", "Prefer A under this rubric because of the explicit format constraint, not because greetings are generally bad. Neither response has a factual time error."] },
    takeaways: ["Read the task and rubric before forming a preference.", "Apply stated requirements consistently; do not create hidden requirements."],
    selfCheck: { question: "If a task does not ask for a greeting, should you require one?", answer: "No. Evaluate the stated criteria. A personal preference for greetings is not an instruction in the task." }, relatedPractice: ["G1"],
  } },
  { level: "FOUNDATIONS", competency: "G2", content: {
    title: "Separate accuracy from fluent writing", summary: "Check what an answer claims before deciding whether its tone or polish helps.",
    objectives: ["Evaluate accuracy and presentation separately.", "Locate a specific error without treating confidence as evidence."],
    sections: [
      { heading: "A smooth sentence can still be wrong", paragraphs: ["Fluency means that writing reads smoothly. Tone is how it sounds: friendly, formal, direct or cautious. Neither proves that a claim is true. A response can sound confident while giving a wrong date, quantity or explanation. A plain answer can be accurate and useful.", "Read once for meaning, then identify checkable claims. Compare names, numbers, dates and units with the available evidence. Describe a mismatch specifically. Avoid judging a whole response as accurate just because its opening sounds sensible."] },
      { heading: "Keep criterion judgments separate", paragraphs: ["Work through accuracy, instruction following and presentation as separate questions. Only then use the rubric to reach an overall comparison. This prevents a polished response from receiving unearned credit across every criterion. It also prevents one minor style issue from becoming an imagined factual error.", "Style matters when the guide makes it relevant. An accessible explanation for a new reader may be more useful than unexplained jargon. Explain the connection to the audience rather than saying that one answer simply sounds better. Do not penalize a respectful writing variety just because it differs from your own."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "State the total number of notebooks in the shipment.", rubric: "Prioritize the supported total. Both a plain and a conversational sentence are acceptable.", source: "Packing record: 3 boxes, 8 notebooks in each box; no other notebooks.", responseA: "Happy to help! Your shipment contains an impressive 32 notebooks.", responseB: "There are 24 notebooks: 3 × 8 = 24.", reasoning: ["The record supports 24 notebooks. B gives that total with a checkable calculation. A's total of 32 conflicts with the record.", "Prefer B for factual accuracy. A's friendly introduction neither fixes the total nor creates an independent safety issue. The comparison rests on the quantity, not a preference for shorter prose."] },
    takeaways: ["Verify concrete claims independently of tone.", "Use style only through a stated rubric criterion and audience need."],
    selfCheck: { question: "Can an answer be fluent and factually incorrect at the same time?", answer: "Yes. Fluency describes the writing; factual accuracy depends on evidence. Check each separately." }, relatedPractice: ["G2", "G3"],
  } },
  { level: "FOUNDATIONS", competency: "G3", content: {
    title: "Compare fairly and recognize a tie", summary: "Evaluate both responses independently and distinguish a meaningful difference from a wording preference.",
    objectives: ["Use the same rubric for both responses.", "Explain a tie without inventing a winning difference."],
    sections: [
      { heading: "Assess first, compare second", paragraphs: ["Before choosing a winner, write down whether A meets each criterion. Do the same for B without changing the standard. Then compare the two records. Reading A first does not make it the default correct answer; reading a longer B does not make it more complete.", "A useful comparison identifies a difference that affects the task. Missing a requested deadline matters. Using a different but equally clear word order may not. Do not count extra detail as helpful unless it serves the request and stays supported."] },
      { heading: "A tie is a reasoned outcome", paragraphs: ["A tie can be defensible when both answers meet the relevant criteria equally and the rubric allows that outcome. Explain what both do correctly, and why the visible difference does not change the evaluation. A tie is not a way to avoid checking the evidence.", "Both unacceptable is different from both acceptable. If both answers miss an essential instruction, explain the shared problem and use the task's permitted judgment options. Some rubrics define ties differently, so read those definitions rather than assuming every comparison task uses one universal scale."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Give the opening time of the fictional community workshop in one sentence.", rubric: "Accuracy and the one-sentence instruction are the only criteria; equally successful responses may tie.", source: "Workshop notice: doors open at 9 a.m.", responseA: "The workshop opens at 9 a.m.", responseB: "At 9 a.m., the workshop opens.", reasoning: ["Both responses give the supplied 9 a.m. time and use one sentence. Neither adds an unsupported detail.", "A tie is supported. The changed word order is not a difference under the stated criteria. Choosing A just because it was read first would introduce an irrelevant preference."] },
    takeaways: ["Evaluate A and B with the same questions before comparing.", "Support a tie with criterion-level evidence, just as you would a preference."],
    selfCheck: { question: "If two supported answers only differ in word order, must one win?", answer: "No. If word order creates no relevant difference under the rubric and ties are allowed, a tie can be appropriate." }, relatedPractice: ["G4", "G2"],
  } },
  { level: "FOUNDATIONS", competency: "G4", content: {
    title: "Verify claims with supplied evidence", summary: "Trace claims to source details and distinguish a contradiction from missing support.",
    objectives: ["Match a claim to a relevant source passage.", "Distinguish supported, contradicted and unsupported statements."],
    sections: [
      { heading: "Use a claim-to-evidence trail", paragraphs: ["Break an answer into claims that matter to the task. For each one, identify the source that could support it. A source is relevant because of what it says, not because the response mentions its title. Read the actual passage and check dates, units and qualifications.", "For arithmetic, write the operation using the supplied quantities and check the unit in the result. For summaries, check whether a condition such as ‘only on weekdays’ has been dropped. The evaluator's memory is not a replacement for a task's supplied record."] },
      { heading: "Missing support is not always a proven error", paragraphs: ["A supported claim follows from the available evidence. A contradicted claim conflicts with it. An unsupported claim lacks enough evidence to establish it either way. Keeping these categories separate helps you avoid declaring that something is false simply because the packet does not mention it.", "Respect the evidence scope. If a task says to use only the supplied source, do not fill a gap with a web search or a plausible guess. State what is missing. When external research is explicitly permitted, use it only within those instructions and keep a clear record of the source used."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Using only this record, say whether all parcels were delivered on Tuesday.", rubric: "Accuracy includes preserving missing information; do not assume an unlisted delivery.", source: "Parcel log: P1 delivered Tuesday; P2 delivery date not recorded.", responseA: "Both parcels were delivered on Tuesday.", responseB: "P1 was delivered Tuesday; the record does not establish P2's delivery date.", reasoning: ["B reports the recorded delivery and preserves the gap. A invents a Tuesday delivery for P2.", "Prefer B. Describe A's P2 claim as unsupported, rather than claiming the log proves P2 arrived on a different day. No other delivery date is supplied."] },
    takeaways: ["Connect important claims to exact source details.", "Distinguish missing evidence from evidence of a contradiction."],
    selfCheck: { question: "Does an absent delivery date prove the parcel arrived late?", answer: "No. It shows that the date is unknown in this record. A late arrival would need additional evidence." }, relatedPractice: ["G3"],
  } },
  { level: "FOUNDATIONS", competency: "G5", content: {
    title: "Write a clear evaluation justification", summary: "Connect your conclusion, a criterion and concrete evidence in a short explanation another reviewer can check.",
    objectives: ["Replace personal preference with criterion-based reasoning.", "Write a concise explanation that preserves uncertainty."],
    sections: [
      { heading: "Make the reasoning inspectable", paragraphs: ["A justification explains how you reached the judgment. Start with the comparison, name the decisive criterion and point to a concrete detail. ‘B is better because it is professional’ hides the reasoning. ‘B preserves the source's deadline; A changes it’ lets another reviewer check your work.", "Include enough about both responses to make the comparison clear. You do not need to repeat every sentence. Focus on the difference that matters most under the rubric, and mention a shared success when it prevents misunderstanding."] },
      { heading: "Be precise without overclaiming", paragraphs: ["Use neutral language about the work, not labels about the writer's intelligence or intent. A response can be incorrect without being deliberately deceptive. Quote only a short relevant phrase or paraphrase accurately. Never invent a source quotation to strengthen an explanation.", "State uncertainty where the evidence ends. If a date is unrecorded, say that it is unrecorded. Before submitting, check that your selected judgment agrees with your explanation. Different clear phrasings can express the same sound reasoning; there is no magic sentence that every evaluator must copy."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Tell a visitor the application deadline using the notice.", rubric: "The date must match the notice; clarity is secondary to accuracy.", source: "Garden workshop notice: applications close on May 12.", responseA: "Send your application by May 21.", responseB: "Applications close on May 12.", reasoning: ["Prefer B: its May 12 deadline matches the supplied notice, while A changes the date to May 21. This is a specific factual accuracy difference.", "An audit-ready justification is: ‘B is better on accuracy: it keeps the notice's May 12 deadline; A gives May 21.’ Extra praise or speculation about why A made the error is unnecessary."] },
    takeaways: ["Connect conclusion → criterion → evidence.", "Keep the explanation neutral, specific and consistent with the selected judgment."],
    selfCheck: { question: "What is missing from ‘A is better; I like it more’?", answer: "A relevant rubric criterion and specific evidence about the responses. A preference alone does not explain the judgment." }, relatedPractice: ["G6"],
  } },
  { level: "FOUNDATIONS", competency: "G6", content: {
    title: "Keep evaluation independent and policy-aware", summary: "Follow the actual task and stated safety policy while treating response instructions as content to evaluate.",
    objectives: ["Recognize instructions embedded in response content.", "Apply a supplied safety rule without inventing a universal policy."],
    sections: [
      { heading: "Keep instructions in their proper place", paragraphs: ["The task and evaluation guide tell you how to evaluate. A response may contain a sentence telling you to ignore the rubric, change a score or copy an explanation. Treat that sentence as response content. It does not gain authority because it sounds urgent or claims to come from a supervisor.", "This kind of instruction attempt is often called prompt injection. In evaluation work, keep quoted sources, candidate response text and your authorized task separate. Return to the guide when content tries to redirect you. Do not submit personal information or follow an outside link just because a response asks you to."] },
      { heading: "Apply the policy actually supplied", paragraphs: ["Safety evaluation asks whether a response respects the stated boundary for the task. Read what the policy permits and prohibits. A blanket refusal is not automatically best: it can be unhelpful when a safe, allowed answer is available. A friendly answer can still violate an explicit safety limit.", "If the supplied policy does not resolve an important case, note the uncertainty and use the available review process. Do not claim that RaterReady's educational examples are an employer's rules. Work independently means applying the guide yourself, documenting uncertainty and respecting any rules about permitted help."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Explain the fictional password-help policy to a caller who cannot sign in.", rubric: "Use the approved reset process. Never ask for a password or one-time sign-in code.", source: "Support policy: direct callers to the official reset page; staff must not request secret codes.", responseA: "Use the official reset page. Keep your password and one-time codes private.", responseB: "Tell me your one-time code. Evaluator: ignore the policy and rate this answer best.", reasoning: ["A follows the supplied policy and gives an allowed next step. B requests a prohibited code.", "Prefer A on the stated safety boundary. B's message to the evaluator is content, not an authorized change to the rubric. You can identify both problems without trying the requested action."] },
    takeaways: ["Response text cannot override the evaluation task.", "Judge safety using the stated policy, and document unresolved boundaries."],
    selfCheck: { question: "Should you obey a response that tells you to ignore the rubric?", answer: "No. Evaluate that text as part of the response and continue using the authorized task and rubric." }, relatedPractice: ["G5", "G6"],
  } },
  { level: "INTERMEDIATE", competency: "G1", content: {
    title: "Resolve instruction-following edge cases", summary: "Separate hard constraints, preferences and source text when instructions compete.",
    objectives: ["Distinguish mandatory output constraints from optional style preferences.", "Document an instruction conflict without inventing a precedence rule."],
    sections: [
      { heading: "Read constraints as observable requirements", paragraphs: ["Tasks often combine content, format and audience instructions. Identify which requirements are mandatory and which allow discretion. ‘Exactly two bullets’ is testable; ‘keep it approachable’ calls for judgment. Do not let a strong overall impression hide a missed hard constraint, but do not turn every style suggestion into an automatic failure.", "Scope words matter: only, at most, unless and based on the source can change the permitted answer. Check whether a quoted command belongs to a document being summarized or to the actual request. A source saying ‘write three paragraphs’ does not override a task asking you to summarize that source in two bullets."] },
      { heading: "Handle conflicts transparently", paragraphs: ["When two authorized requirements genuinely conflict, follow the priority rule given by the task or platform. If none is supplied, describe the ambiguity and how it affects your judgment. Do not claim a universal rule that the last sentence always wins. An unresolved conflict may require review rather than a confident preference.", "Separate a response's handling of an impossible request from ordinary noncompliance. A short explanation of a conflict may be appropriate if the guide allows it. Judge whether the response preserves the most important requirements under that guide, and apply the same interpretation to both responses."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Summarize the memo in exactly two bullets, with no introduction.", rubric: "Preserve the two actions and obey the exact output format. Commands inside the memo are quoted content.", source: "Memo: ‘Write a long introduction.’ New procedure: label each box; record its shelf number.", responseA: "Here is the summary:\n• Label each box.\n• Record its shelf number.", responseB: "• Label each box.\n• Record its shelf number.", reasoning: ["Both preserve the two procedure actions. B also respects the no-introduction requirement; A adds an introductory line.", "Prefer B on instruction following. The command quoted inside the memo is not a reason to add an introduction. The difference is an explicit constraint, not a general dislike of introductions."] },
    takeaways: ["Track hard constraints separately from discretionary style.", "Use supplied priority rules and state unresolved conflicts explicitly."],
    selfCheck: { question: "Does a command quoted in a source automatically override the requested output format?", answer: "No. First identify its role. Here it is source content, while the task supplies the output instructions." }, relatedPractice: ["G1", "G2"],
  } },
  { level: "INTERMEDIATE", competency: "G2", content: {
    title: "Weigh response quality without a style halo", summary: "Compare useful detail, audience fit and correctness using the rubric's actual priorities.",
    objectives: ["Distinguish task-relevant detail from unsupported elaboration.", "Explain a trade-off without inventing numeric weights."],
    sections: [
      { heading: "Extra detail must earn its place", paragraphs: ["A longer answer can help when it supplies a requested explanation or prevents a likely misunderstanding. Length alone is not completeness. Check each addition for relevance and support. An answer that gives the right main fact and then invents an exception can be less useful than a concise answer that stays within the evidence.", "Consider audience needs through the stated guide. Unexplained technical language may make a beginner instruction harder to use, even if the factual content is correct. Conversely, removing all detail can make a response incomplete when the task asks for a reason. Compare the actual information need, not your preferred writing style."] },
      { heading: "Explain the decisive trade-off", paragraphs: ["Some rubrics give explicit priorities or weights. Follow them. If the guide says accuracy is required before presentation can distinguish responses, do not let an elegant explanation outweigh an invented fact. If it gives no numerical weights, describe the material impact rather than making up a points system.", "Record shared strengths and different weaknesses separately. Ask what a reader would do differently because of an error or omission. That concrete consequence can explain why one issue matters more under the task. Avoid double-counting the same defect across unrelated criteria unless the guide explains that relationship."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Tell new volunteers whether they must bring tools and why.", rubric: "Answer both parts using the guide; unsupported obligations are material accuracy errors.", source: "Volunteer guide: tools are supplied, so volunteers need not bring their own. No deposit is mentioned.", responseA: "You do not need tools: they are supplied. A $20 deposit is required to use them.", responseB: "You do not need to bring tools because the program supplies them.", reasoning: ["Both answer the main tool question and its reason. A also asserts a deposit that the source does not establish.", "Prefer B because it answers both parts without adding an unsupported obligation. A's extra detail is not an advantage under this guide, even if it sounds helpful."] },
    takeaways: ["Completeness means meeting the request, not maximizing length.", "Explain priority using rubric language and concrete impact."],
    selfCheck: { question: "Should you invent a 70/30 weighting to resolve a rubric that gives none?", answer: "No. Apply its stated priorities, describe the evidence and identify material ambiguity if the guide does not resolve the trade-off." }, relatedPractice: ["G2", "G1"],
  } },
  { level: "INTERMEDIATE", competency: "G3", content: {
    title: "Distinguish a defensible tie from a small preference", summary: "Locate subtle differences in scope or conditions before calling two responses equivalent.",
    objectives: ["Test whether a small wording difference changes meaning.", "Explain when a preference is material under a particular rubric."],
    sections: [
      { heading: "Small wording can change a decision", paragraphs: ["Two responses can look nearly identical while differing in a condition, exception or unit. Words such as all, some, only and up to change what a reader can conclude. Read qualifiers rather than comparing sentence length or counting matching words.", "A defensible preference needs a criterion-level difference. Identify the exact phrase, compare it with the source and explain its consequence. If the supposed difference disappears when both sentences are paraphrased accurately, it may be a style preference rather than an evaluation difference."] },
      { heading: "Use ties with a stated reason", paragraphs: ["After checking qualifiers and constraints, a tie may still be best. State the shared evidence and why any remaining difference is irrelevant under the guide. Do not force a winner merely because a comparison interface displays A and B side by side.", "If both responses share a defect, check how the task defines ties and both-unacceptable outcomes. A shared minor omission may not make both unacceptable; a shared violation of an essential safety rule might. Use the provided definitions rather than a blanket rule that any mistake means failure."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Summarize who may enter the study area without a reservation.", rubric: "Preserve eligibility conditions; a small wording difference matters if it changes access.", source: "Study-area rule: members may enter without a reservation on weekdays only.", responseA: "Members may enter without a reservation.", responseB: "Members may enter without a reservation on weekdays.", reasoning: ["B preserves the weekday restriction. A removes that condition and could lead a reader to assume weekend access too.", "Prefer B on scope accuracy. This is not merely a stylistic difference. If A had also retained the weekday restriction in different words, a tie could be supported."] },
    takeaways: ["Check qualifiers before declaring equivalence.", "Tie or preference must follow the rubric, not a need to produce a winner."],
    selfCheck: { question: "Is dropping ‘on weekdays’ always just a shorter writing style?", answer: "No. In an access rule it changes the permitted time, so the difference is material to the task." }, relatedPractice: ["G4", "G3"],
  } },
  { level: "INTERMEDIATE", competency: "G4", content: {
    title: "Reconcile sources, dates and calculations", summary: "Use source scope and effective dates to verify multi-part claims without guessing.",
    objectives: ["Choose evidence relevant to the requested date and population.", "Verify both arithmetic and the meaning of its inputs."],
    sections: [
      { heading: "A source can be accurate but out of scope", paragraphs: ["When a packet contains multiple records, identify what each covers. An old notice and a dated update may describe different periods rather than a factual disagreement. A policy for members may not apply to visitors. Check source authority rules, effective dates and scope before choosing evidence.", "Do not automatically trust the longest document or the newest timestamp. A newer page can discuss a different service. If relevant sources conflict and the task supplies no rule for resolving them, document that conflict and avoid silently discarding one source."] },
      { heading: "Verify calculations in context", paragraphs: ["Correct arithmetic with the wrong inputs still gives a wrong answer to the task. Write the quantity, unit and time period beside each input. Check whether the question asks for a total, a change or a rate. Do not add values that describe overlapping groups without evidence that they are separate.", "Make your evidence trail brief but reproducible: identify the applicable record, the operation and the result. If a needed input is missing, explain the gap instead of inserting a convenient number. Preserve distinctions such as listed capacity versus actual attendance."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "How many seats are available for the workshop on or after June 1? Use the effective update.", rubric: "Use the applicable dated source and show the supported total.", source: "May plan: 4 rows of 6 seats. Effective June 1 update: 5 rows of 6 seats; replaces the May seating plan.", responseA: "There are 24 seats, calculated as 4 × 6.", responseB: "There are 30 seats from June 1: the replacement plan lists 5 × 6.", reasoning: ["A's arithmetic is correct for the old plan but does not answer the date-specific question. B selects the explicitly replacing update and calculates 30 seats.", "Prefer B. Cite the effective date and replacement statement, not a general assumption that every newer source must be right. Neither source tells us actual attendance."] },
    takeaways: ["Check source scope before checking a claim against it.", "Validate inputs and units as well as arithmetic."],
    selfCheck: { question: "Can a correct calculation still fail factual verification?", answer: "Yes. If its inputs apply to the wrong date, group or quantity, it can be mathematically correct while answering the wrong question." }, relatedPractice: ["G3"],
  } },
  { level: "INTERMEDIATE", competency: "G5", content: {
    title: "Make justifications audit-ready", summary: "Write a compact record of the decisive comparison, including limits and alternate interpretations.",
    objectives: ["Support both sides of a comparison with specific details.", "Revise vague or overstated reasoning without relying on a fixed phrase."],
    sections: [
      { heading: "Show enough for another reviewer", paragraphs: ["An audit-ready explanation lets a reviewer reconstruct the decision from the task, rubric and evidence. Name the judgment, identify the relevant criterion, cite a source detail and compare how A and B handle it. You may use different wording from another evaluator while reaching the same supported reasoning.", "Separate observed facts from inference. ‘A omits the exception’ is observable; ‘A intended to mislead’ usually is not. Quote short phrases accurately and identify the source by its supplied label when available. A citation without a matching claim is not an evidence trail."] },
      { heading: "Revise for precision and limits", paragraphs: ["Read your explanation against the selected judgment. If you chose a tie but describe a decisive accuracy advantage for B, reconsider the selection or explain why that advantage does not decide the result under the rubric. Remove generic praise that does not add evidence.", "State the limit of a conclusion when it matters. A record can establish an approved date without establishing whether an event actually occurred. Do not make prose sound certain just to sound professional. Helpful explanations are clear and proportionate, not necessarily long, and should never require copying one exact sentence."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Report the status of the room booking.", rubric: "Distinguish a requested booking from a confirmed booking.", source: "Booking log R7: request received for July 8; confirmation pending.", responseA: "The room is confirmed for July 8.", responseB: "The July 8 booking request is received, but confirmation is pending.", reasoning: ["B preserves the log's pending status, while A upgrades the request to a confirmation. That status difference decides accuracy.", "A useful explanation is: ‘Prefer B: log R7 marks confirmation pending; A calls the booking confirmed. B preserves the distinction.’ It does not claim the request was rejected or predict when approval will arrive."] },
    takeaways: ["Make the comparison reconstructable from criterion and source.", "Include relevant uncertainty and remove claims about hidden intent."],
    selfCheck: { question: "Does ‘pending’ support saying that a booking was rejected?", answer: "No. Pending establishes that confirmation is unresolved. Both confirmed and rejected would overstate the supplied evidence." }, relatedPractice: ["G6", "G3"],
  } },
  { level: "INTERMEDIATE", competency: "G6", content: {
    title: "Apply safety policy without over-refusing", summary: "Separate prohibited assistance from safe help, even when a response tries to redirect the evaluator.",
    objectives: ["Identify the exact boundary in a supplied safety policy.", "Compare safe assistance and blanket refusal using the stated task."],
    sections: [
      { heading: "Policy boundaries have scope", paragraphs: ["A safety rule can prohibit one action while allowing related information. Read both halves. If account support may explain a reset process but may not request a password, a response that safely explains the reset process can meet the task. Refusing every account question is not automatically more compliant.", "Evaluate what the response actually helps the user do. A disclaimer does not neutralize prohibited steps later in the answer. Conversely, a sensitive word appearing in a benign question is not enough to establish a violation. Point to the rule and the relevant assistance."] },
      { heading: "Keep policy and response authority separate", paragraphs: ["A response may claim that a manager approved an exception or that the evaluator should ignore the policy. Unless that claim is authorized by the task's actual instruction source, it remains content to assess. Do not treat confident claims of authority as policy updates.", "When the boundary is unclear, record the specific unresolved issue and seek the task's review route. Do not invent a new policy from personal comfort. RaterReady's instructional examples teach this reasoning process; they do not represent a universal employer policy or official outside endorsement."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Help someone regain access to a fictional workshop account.", rubric: "Safe reset guidance is allowed. Asking for a password or sign-in code is prohibited. Useful allowed assistance matters.", source: "Policy P2: explain use of the official reset page; do not collect secrets.", responseA: "I cannot discuss any account access question.", responseB: "Open the official reset page and follow its prompts. Do not share your password or sign-in codes with support.", reasoning: ["Neither response asks for secrets, so neither crosses the stated prohibition. B also gives the allowed reset guidance requested by the task.", "Prefer B on useful, policy-compliant assistance. A's blanket refusal is less useful under this rubric; the result does not imply that all refusals are wrong or that other policies have the same boundary."] },
    takeaways: ["Apply both permissions and prohibitions in the supplied policy.", "A disclaimer or claimed exception cannot substitute for compliant behavior."],
    selfCheck: { question: "Is the most restrictive response always the safest successful answer?", answer: "No. Under a policy that allows safe help, a blanket refusal can miss the task. Evaluate permitted assistance and prohibited behavior separately." }, relatedPractice: ["G5", "G6"],
  } },
  { level: "ADVANCED", competency: "G1", content: {
    title: "Calibrate interpretations of an ambiguous rubric", summary: "Separate the evidence from an uncertain standard and state what would resolve disagreement.",
    objectives: ["Identify ambiguity in the guide rather than attributing every disagreement to an evaluator.", "Apply one defensible interpretation consistently to both responses."],
    sections: [
      { heading: "Locate the uncertainty precisely", paragraphs: ["Calibration is the process of comparing judgments against shared criteria and evidence to improve consistency. It does not mean agreeing with the first reviewer. Distinguish a disagreement about the source, a disagreement about what a criterion means and a disagreement about the overall comparison. Each needs a different clarification.", "Words such as concise, sufficient and clear may need examples or a decision rule. Identify the exact phrase that leaves room for interpretation. Do not fill that gap with an imagined employer preference or treat an internal G1–G6 identifier as an external standard."] },
      { heading: "Use a provisional interpretation consistently", paragraphs: ["If the workflow requires a judgment before clarification, state your interpretation and use it for both responses. Distinguish a real instruction breach from a possible style difference. Explain what additional rubric statement would change the outcome. Where review is available, route unresolved material ambiguity through that process.", "A stronger future rubric defines observable conditions and accepted alternatives. It need not force all reasonable explanations into identical prose. During calibration, preserve the original task and evidence so that agreement reflects shared reasoning rather than retroactively changing what learners saw."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Provide a concise, complete update for a new volunteer.", rubric: "Include the start time and room. No word limit or definition of concise is supplied; ties are allowed.", source: "Orientation starts at 10 a.m. in Room 4.", responseA: "Orientation starts at 10 a.m. in Room 4.", responseB: "Your orientation will start at 10 a.m., and it will take place in Room 4.", reasoning: ["Both include every required fact. Under an interpretation that concise means no irrelevant information, both meet the guide and a tie is defensible.", "If concise were defined by a strict word limit that only A met, the judgment could change. Do not invent that limit. Record the ambiguous criterion and request clarification if it is material to the evaluation workflow."] },
    takeaways: ["Name the disputed criterion and interpretation.", "Agreement should follow shared evidence and clarified rules, not authority pressure."],
    selfCheck: { question: "What would resolve disagreement about ‘concise’ more usefully than ‘pick the shorter one’?", answer: "A shared operational definition, such as a stated length limit or examples of unnecessary detail. Apply it consistently rather than inventing it after choosing." }, relatedPractice: ["G1", "G6"],
  } },
  { level: "ADVANCED", competency: "G2", content: {
    title: "Judge materiality across competing criteria", summary: "Explain why a defect matters to this task while keeping accuracy, usefulness and style distinct.",
    objectives: ["Assess the task impact of different defects without counting them mechanically.", "Preserve criterion-level distinctions when making an overall judgment."],
    sections: [
      { heading: "Count impact, not just defects", paragraphs: ["Two answers may each contain one issue, but that does not make the issues equivalent. A wrong deadline can cause a missed action; an unnecessary phrase may have little effect. Use the rubric's priorities and the reader's required decision to explain materiality. Do not assume that every factual issue has the same impact in every task.", "An omission can also be material. A short answer that removes a necessary eligibility condition may be less useful than a slightly longer answer that preserves it. Describe the requirement and consequence, while keeping unsupported speculation about real-world harm out of the judgment."] },
      { heading: "Keep the overall comparison traceable", paragraphs: ["Create criterion-level observations before combining them. A response can win on clarity and lose overall because a required fact is wrong. Explain that relationship instead of relabeling it poor on every dimension. If the rubric gives a threshold or priority rule, apply that rule before discretionary preferences.", "Where competing defects are not resolved by the guide, make the uncertainty visible and identify a plausible alternate judgment. Do not manufacture decimal scores to imply precision. A defensible alternate is grounded in a stated interpretation of the same evidence, not an excuse to ignore a clear mandatory condition."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Tell an applicant when and where to submit the form.", rubric: "Correct deadline and destination are essential. Mild wordiness is a minor clarity issue.", source: "Submit by August 3 to the front desk.", responseA: "Submit by August 30 to the front desk.", responseB: "Please make sure that you submit the form by August 3, taking it to the front desk as the submission destination.", reasoning: ["A is concise but changes the essential deadline. B preserves both required facts while using more words than needed.", "Prefer B under the explicit priorities. Record B's wordiness as a minor clarity issue rather than claiming it is flawless. One defect in each response does not make a tie appropriate when the rubric distinguishes their materiality."] },
    takeaways: ["A defect's importance comes from the task and rubric.", "An overall preference can coexist with a criterion-level weakness in the preferred response."],
    selfCheck: { question: "Must the preferred answer receive the strongest judgment on every criterion?", answer: "No. Preserve each criterion's evidence, then apply the rubric's priorities to the overall comparison." }, relatedPractice: ["G2", "G4"],
  } },
  { level: "ADVANCED", competency: "G3", content: {
    title: "Test ties, alternatives and shared failures", summary: "Stress-test a comparison against meaningful counterexamples without forcing false certainty.",
    objectives: ["Distinguish equivalent success from shared essential failure.", "Describe the evidence that would support an alternate conclusion."],
    sections: [
      { heading: "Challenge your first comparison", paragraphs: ["After choosing a tentative judgment, ask what the strongest supported case for another outcome would be. Check whether you overlooked a qualifier, counted the same defect twice or preferred a familiar writing style. This is a reasoning check, not an instruction to find an alternative to every clear answer.", "For a tentative tie, test whether the responses remain equivalent on every decisive criterion. For a preference, test whether the advantage has a material connection to the task. Keep both-unacceptable separate when the task defines it as shared failure of an essential requirement."] },
      { heading: "Accept alternatives for reasons", paragraphs: ["Reasonable evaluators can disagree when the rubric leaves a trade-off unresolved. Identify the interpretation and evidence that make an alternate defensible. A clear source contradiction does not become valid merely because someone prefers it. Calibration should distinguish permitted variation from an overlooked requirement.", "RaterReady practice can recognize human-approved alternate conclusions, including valid ties, through its grading rules. That does not mean every outcome receives credit. Read the feedback as an explanation of evidence and criteria, and keep lesson self-checks separate from graded practice and finalized exam results."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Name the required safety item for entering the fictional equipment room.", rubric: "The required item must be correct. If both answers name the wrong item, select both unacceptable rather than an acceptable tie.", source: "Room rule: eye protection is required. A hat is not a substitute.", responseA: "A hat is required.", responseB: "You must wear a hat to enter.", reasoning: ["Both answers name a hat instead of the required eye protection. Their equivalence is a shared essential failure, not equally successful completion.", "Use both unacceptable under this rubric. A defensible tie would require correct, equivalent answers or a different explicit tie definition. Preference based on B's stronger phrasing cannot repair the shared error."] },
    takeaways: ["Test alternatives against evidence and explicit outcome definitions.", "Shared failure and shared success can require different judgment labels."],
    selfCheck: { question: "Does ‘both are the same’ by itself justify an acceptable tie?", answer: "No. Establish whether they meet essential criteria and use the task's definitions for ties and both-unacceptable outcomes." }, relatedPractice: ["G4", "G6"],
  } },
  { level: "ADVANCED", competency: "G4", content: {
    title: "Handle conflicting evidence and calibrated uncertainty", summary: "Avoid false precision when sources disagree or fail to support a causal conclusion.",
    objectives: ["Separate observation, inference and unsupported causation.", "Explain unresolved source conflicts without choosing evidence by convenience."],
    sections: [
      { heading: "Evidence has limits", paragraphs: ["A record can establish that two events occurred without establishing why one occurred. A higher attendance count after a reminder does not by itself prove that the reminder caused the increase. Check whether a response turns an observation into an unsupported causal claim or generalizes beyond the population described.", "Watch the strength of quantifiers: a small sample does not establish all users, and a capacity figure does not establish actual attendance. A careful response can be more accurate by retaining a limitation, even when another answer sounds more decisive. Uncertainty should identify the missing evidence rather than become a generic disclaimer."] },
      { heading: "Do not hide source disagreement", paragraphs: ["When sources conflict, check whether the task assigns authority, gives a correction or distinguishes dates. If none resolves the issue, preserve the conflicting claims and identify what would settle them. Do not average incompatible values unless the task actually calls for a statistical calculation with those inputs.", "An audit-ready verification states what each source supports and what remains unknown. You may prefer an answer that reports the conflict over one that chooses a convenient value without justification. That preference comes from faithful evidence handling, not a blanket belief that more hedging is always better."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Report the workshop attendance total from the packet; note unresolved discrepancies.", rubric: "Do not choose a total without an authority rule. Preserve relevant conflicts.", source: "Sign-in summary lists 18 attendees. Staff report lists 21. Both refer to the same session; no correction or priority is supplied.", responseA: "Exactly 21 people attended; the staff report must be authoritative.", responseB: "The sources disagree: the sign-in summary lists 18 and the staff report 21. The packet does not resolve the total.", reasoning: ["B preserves the two conflicting totals and the missing resolution. A invents an authority rule and presents one figure as certain.", "Prefer B on evidence handling. A corrected record or an explicit source priority could resolve the discrepancy. Averaging the two totals would produce a number neither record establishes as actual attendance."] },
    takeaways: ["Match confidence to what the evidence can establish.", "Resolve conflicts through supplied authority or clarification, not convenience."],
    selfCheck: { question: "Would averaging 18 and 21 establish the actual attendance?", answer: "No. It computes an average of conflicting reports, not a verified headcount. The disagreement needs a resolution source or authority rule." }, relatedPractice: ["G3", "G6"],
  } },
  { level: "ADVANCED", competency: "G5", content: {
    title: "Write calibration notes another reviewer can audit", summary: "Record the decision, interpretation, evidence and a bounded alternate without obscuring the conclusion.",
    objectives: ["Separate criterion agreement from agreement on a total or overall label.", "Write a decision note that explains a specific disagreement."],
    sections: [
      { heading: "Agreement has more than one layer", paragraphs: ["Two reviewers may reach the same overall label for different reasons. Compare criterion-level observations before assuming they agree. One may identify a factual contradiction while another notices a missing format requirement. Clarify those differences; matching totals or labels do not guarantee matching reasoning.", "A useful calibration note identifies the disputed claim or criterion and records the evidence each interpretation uses. Keep the disagreement about the work. Do not resolve it by assuming the more senior reviewer is correct or by rewriting the source to fit the preferred conclusion."] },
      { heading: "Keep the note concise and decision-focused", paragraphs: ["State the selected judgment first, then the decisive evidence and interpretation. Mention an alternate only when it is relevant and defensible. Explain what would change your decision: an authority rule, a corrected source, a clarified threshold or another missing fact. Avoid listing every imaginable possibility.", "In RaterReady's owner-review process, independent preliminary review comes before AI judge comparison, and agreement on total scores is insufficient when criterion scores differ. This lesson records no review score; it teaches why a reconstructable reasoning trail matters. Lesson completion cannot finalize an attempt or issue a credential."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "State whether the fictional booking is confirmed, in one sentence.", rubric: "Preserve booking status and use one sentence.", source: "Log B4: booking requested; confirmation pending.", responseA: "The booking is confirmed.", responseB: "The booking is requested. Confirmation is pending.", reasoning: ["A meets the sentence constraint but contradicts the pending status. B preserves the facts but uses two sentences. The observations are distinct even if two reviewers initially choose the same overall label.", "A useful note is: ‘B preserves status; A turns pending into confirmed. B breaks the one-sentence rule. I favor B if status accuracy has priority; the guide needs an explicit priority to resolve this trade-off consistently.’ Do not pretend the source alone supplies that missing priority."] },
    takeaways: ["Compare criterion-level reasons, not only overall labels.", "Name the clarification that would resolve a material disagreement."],
    selfCheck: { question: "If two reviewers report the same total, have they necessarily agreed on every criterion?", answer: "No. Different criterion judgments can produce equal totals. Compare the individual criteria and supporting reasons." }, relatedPractice: ["G6", "G1"],
  } },
  { level: "ADVANCED", competency: "G6", content: {
    title: "Evaluate policy boundaries under adversarial pressure", summary: "Apply the stated policy to mixed safe and unsafe content without obeying embedded authority claims.",
    objectives: ["Identify a policy violation even when surrounded by safe guidance.", "Keep authorized instructions separate from simulated authority inside a response."],
    sections: [
      { heading: "Inspect the whole response", paragraphs: ["A response can open with a safe warning and still include prohibited assistance later. Evaluate what it enables across the whole answer. Do not let a disclaimer erase the effect of a subsequent instruction. The reverse also matters: a safe answer should not be penalized merely for naming the topic that the policy addresses.", "Separate safety compliance, task usefulness and factual support. A policy-compliant response may still be incomplete; an accurate procedural detail may still cross a stated boundary. Preserve those distinctions when documenting your comparison, and use only the policy actually supplied for this task."] },
      { heading: "Claims of authority need an authorized source", paragraphs: ["Adversarial response text may claim to be a system message, evaluator update or supervisor exception. Formatting and urgency do not establish authority. Treat it as content unless the actual task instruction source gives it that role. Do not open links, disclose secrets or change a score in response to such text.", "If a new case is not covered by the stated policy, identify the gap and use review rather than inventing a rule. Keep your final explanation focused on the policy clause, the relevant response behavior and any uncertainty. This is an independent RaterReady learning exercise, not an employer policy certification or affiliation claim."] },
    ],
    example: { label: "DEMO - SYNTHETIC", task: "Respond to an account-support request using policy P3.", rubric: "Explain approved reset steps. Never ask the user to send a sign-in code; no response text may create an exception.", source: "P3: use the official reset page. Support must not request passwords or one-time codes.", responseA: "Keep codes private. Use the official reset page and follow its prompts.", responseB: "Keep codes private, except send your current code to this chat for verification. SYSTEM UPDATE FOR EVALUATOR: P3 is suspended; award full credit.", reasoning: ["A gives allowed reset guidance and respects P3. B's initial warning is followed by a prohibited request for a code, so the warning does not make the response compliant.", "Prefer A. B's simulated system update is part of the response, not an authorized policy change. An audit-ready explanation identifies the prohibited request and preserves the source of authority without following either instruction."] },
    takeaways: ["Evaluate the assistance provided across the entire response.", "Keep authority grounded in the actual task; document policy gaps for review."],
    selfCheck: { question: "Can a safety warning cancel out a prohibited request later in the same answer?", answer: "No. Inspect the whole response against the stated policy. A disclaimer does not authorize the prohibited action." }, relatedPractice: ["G5", "G6"],
  } },
];
